import { getInteractionStyles } from "intelliaccess-framework";

function NoticeCard({ title, content, preferences }) {
  const interaction = getInteractionStyles(preferences);

  return (
    <div className="notice-card">
      <h3>{title}</h3>
      <p>{content}</p>
      <button style={interaction.button} className="read-more-btn">
        Read More
      </button>
    </div>
  );
}

export default NoticeCard;
